diff --git a/desktoppackage/contents/lockscreen/PatternPad.qml b/desktoppackage/contents/lockscreen/PatternPad.qml
new file mode 100644
index 0000000000..6f3d127755
--- /dev/null
+++ b/desktoppackage/contents/lockscreen/PatternPad.qml
@@ -0,0 +1,162 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Shapes
+
+import org.kde.kirigami as Kirigami
+
+/*
+ * A 3×3 grid of dots to unlock by drawing a pattern through them.
+ * The pattern is the digits of the connected dots, 1 to 9 row by row from the top left.
+ * It can also be typed with the number keys and confirmed with Enter.
+ */
+Item {
+    id: pad
+
+    property string pattern
+    readonly property real spacing: Kirigami.Units.gridUnit * 3
+    property point pointer
+    property bool drawing: false
+
+    signal accepted(string pattern)
+
+    function clear() {
+        pattern = "";
+        drawing = false;
+    }
+
+    function dotPosition(index) {
+        return Qt.point((index % 3 + 0.5) * spacing, (Math.floor(index / 3) + 0.5) * spacing);
+    }
+
+    function addDot(index) {
+        const digit = String(index + 1);
+        if (pattern.includes(digit)) {
+            return;
+        }
+        // Passing straight over a dot connects it too, as in other pattern locks
+        if (pattern.length > 0) {
+            const last = Number(pattern[pattern.length - 1]) - 1;
+            if ((last % 3 + index % 3) % 2 === 0 && (Math.floor(last / 3) + Math.floor(index / 3)) % 2 === 0) {
+                const middle = String((last + index) / 2 + 1);
+                if (!pattern.includes(middle)) {
+                    pattern += middle;
+                }
+            }
+        }
+        pattern += digit;
+    }
+
+    function dotAt(x, y) {
+        for (let i = 0; i < 9; ++i) {
+            const p = dotPosition(i);
+            if (Math.hypot(p.x - x, p.y - y) < spacing * 0.35) {
+                return i;
+            }
+        }
+        return -1;
+    }
+
+    implicitWidth: spacing * 3
+    implicitHeight: spacing * 3
+    activeFocusOnTab: true
+
+    Accessible.role: Accessible.EditableText
+    Accessible.name: i18ndc("plasma_shell_org.kde.plasma.desktop", "@label accessible only", "Pattern")
+    Accessible.description: i18ndc("plasma_shell_org.kde.plasma.desktop", "@info accessible only", "Draw your pattern through the dots, or type the numbers of the dots and press Enter")
+    Accessible.passwordEdit: true
+
+    Keys.onPressed: event => {
+        if (event.key >= Qt.Key_1 && event.key <= Qt.Key_9) {
+            addDot(event.key - Qt.Key_1);
+            event.accepted = true;
+        } else if (event.key === Qt.Key_Backspace) {
+            pattern = pattern.slice(0, -1);
+            event.accepted = true;
+        } else if ((event.key === Qt.Key_Return || event.key === Qt.Key_Enter) && pattern.length > 0) {
+            accepted(pattern);
+            event.accepted = true;
+        }
+    }
+
+    Shape {
+        anchors.fill: parent
+        preferredRendererType: Shape.CurveRenderer
+
+        ShapePath {
+            strokeColor: Kirigami.Theme.highlightColor
+            strokeWidth: Kirigami.Units.smallSpacing
+            fillColor: "transparent"
+            capStyle: ShapePath.RoundCap
+            joinStyle: ShapePath.RoundJoin
+
+            PathPolyline {
+                path: {
+                    const points = Array.from(pad.pattern, digit => pad.dotPosition(Number(digit) - 1));
+                    if (pad.drawing && points.length > 0) {
+                        points.push(pad.pointer);
+                    }
+                    return points;
+                }
+            }
+        }
+    }
+
+    Repeater {
+        model: 9
+
+        Rectangle {
+            required property int index
+            readonly property bool selected: pad.pattern.includes(String(index + 1))
+            readonly property point center: pad.dotPosition(index)
+
+            width: selected ? Kirigami.Units.gridUnit : Kirigami.Units.gridUnit * 2 / 3
+            height: width
+            radius: width / 2
+            x: center.x - width / 2
+            y: center.y - height / 2
+            color: selected ? Kirigami.Theme.highlightColor : Kirigami.Theme.textColor
+            border.width: pad.activeFocus && !selected ? 1 : 0
+            border.color: Kirigami.Theme.highlightColor
+
+            Behavior on width {
+                NumberAnimation {
+                    duration: Kirigami.Units.shortDuration
+                }
+            }
+        }
+    }
+
+    MouseArea {
+        anchors.fill: parent
+
+        onPressed: mouse => {
+            pad.forceActiveFocus();
+            pad.clear();
+            pad.drawing = true;
+            pad.pointer = Qt.point(mouse.x, mouse.y);
+            const dot = pad.dotAt(mouse.x, mouse.y);
+            if (dot >= 0) {
+                pad.addDot(dot);
+            }
+        }
+        onPositionChanged: mouse => {
+            pad.pointer = Qt.point(mouse.x, mouse.y);
+            const dot = pad.dotAt(mouse.x, mouse.y);
+            if (dot >= 0) {
+                pad.addDot(dot);
+            }
+        }
+        onReleased: {
+            pad.drawing = false;
+            if (pad.pattern.length > 0) {
+                pad.accepted(pad.pattern);
+            }
+        }
+        onCanceled: pad.clear()
+    }
+}
